import type { ImportArtistEntry, ImportLabelEntry } from './adminApi';

/**
 * Pure edits of a Draft v2 draft's ordered Artist entries and label. Every edit returns the same array when nothing changes,
 * and new objects keep the schema key order, so an unchanged value never reads as an edit (draftChanges compares JSON).
 */

/** The server's entry limit (DRAFT_V2_LIMITS.artists, src/administration/import/adminImportDraft.ts). */
export const ARTIST_ENTRY_LIMIT = 20;
/** Case-insensitive name identity as the server folds cleaned names: NFC, trimmed, lower-cased. */
export const foldEntryName = (value: string) => value.normalize('NFC').trim().toLowerCase();
// Mirrors normalizeJoinPhrase (src/models/catalogCredit.ts) so a phrase the server refuses is caught before saving; the server stays authoritative.
const loneSurrogate = /[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/;
const forbiddenPhrase = /[\p{Cc}\p{Cf}\p{Zl}\p{Zp}\p{Co}\p{Cn}\u034F\u115F\u1160\u17B4\u17B5\u2800\u3164\uFFA0]/u;
const visibleCharacter = /[^\p{White_Space}\p{M}\p{Default_Ignorable_Code_Point}]/u;
const fusingEdge = /^[\p{M}\p{Emoji_Modifier}\p{Regional_Indicator}\u1160-\u11FF\uD7B0-\uD7FF]|[\p{Regional_Indicator}\u1100-\u115F\uA960-\uA97F]$/u;
// In the order cleanText and parseImportName (src/administration/import) check a name: control characters and lone surrogates
// as typed, then control and formatting characters left after NFC and trimming (which drops an edge U+FEFF).
const invalidName = (name: string) => /\p{Cc}/u.test(name) || loneSurrogate.test(name) || /[\p{Cc}\p{Cf}]/u.test(name.normalize('NFC').trim());
